import sys

def numoffbt(arr, n):
    MOD = 1000000007
    arr.sort()
    dp = {}
    for x in arr:
        dp[x] = 1

    for i in range(n):
        val = arr[i]
        for j in range(i + 1):
            left = arr[j]
            if val % left != 0:
                continue
            right = val // left
            if right not in dp:
                continue
            count_left = dp[left]
            count_right = dp[right]
            ways = (count_left * count_right) % MOD
            dp[val] = (dp[val] + ways) % MOD

    total = 0
    for x in arr:
        total = (total + dp[x]) % MOD

    return total

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    arr = []
    idx = 1
    for _ in range(n):
        arr.append(int(data[idx]))
        idx += 1
    result = numoffbt(arr, n)
    print(result)

if __name__ == "__main__":
    main()
